async function signup(dto: SignupDto) {
  const tenant = await db.tenants.create({ name: dto.name, tier: 'free', status: 'PROVISIONING' });
  await sfn.startExecution({ stateMachineArn: PROVISION_ARN, input: JSON.stringify({ tenantId: tenant.id }) });
  return { tenantId: tenant.id, status: 'PROVISIONING' };
}

async function handleOrder(req: TenantRequest) {
  const tenant = await cache.getTenant(req.tenantId);
  if (tenant.status !== 'ACTIVE') throw new ServiceUnavailableError('Tenant not ready');
  return orderService.create(req.tenantId, req.body);
}
